// Prepare WhatsApp Business API interactive message
const item = $json;
const phone = item.passenger?.phone_number || '+60123456789';
const threadId = item.thread_id;
const flight = item.disruption?.recommended_flight;
const dep = item.disruption?.departure_time;
const body = item.whatsapp_template?.body || `Flight canceled. We reserved seat on ${flight} departing ${dep}.`;

return {
  recipient_phone: phone,
  message_payload: {
    messaging_product: 'whatsapp',
    to: phone,
    type: 'interactive',
    interactive: {
      type: 'button',
      header: {
        type: 'text',
        text: item.whatsapp_template?.header || '✈️ SynapseAir Flight Disruption Alert'
      },
      body: {
        text: body
      },
      footer: {
        text: `Thread: ${threadId} • Powered by DeepSeek + Atlas`
      },
      action: {
        buttons: [
          {
            type: 'reply',
            reply: {
              id: `APPROVE:${threadId}`,
              title: '✓ 1-Click Accept'
            }
          },
          {
            type: 'reply',
            reply: {
              id: `REJECT:${threadId}`,
              title: '✕ Decline / Re-route'
            }
          }
        ]
      }
    }
  }
};
